begin;
create or replace function workshop_private.norm83(p text) returns text language sql immutable set search_path='' as $$select regexp_replace(lower(regexp_replace(coalesce(p,''),'\([^)]*\)','','g')),'[^[:alnum:]]','','g')$$;
create table if not exists workshop_private.codes83(section text not null,name text not null,code text not null,primary key(section,code));
create table if not exists workshop_private.product_codes83(product_id uuid primary key references workshop_private.catalog75(id) on delete cascade,code text not null);
alter table workshop_private.codes83 enable row level security;alter table workshop_private.product_codes83 enable row level security;
revoke all on workshop_private.codes83,workshop_private.product_codes83 from public,anon,authenticated;
create or replace function public.workshop_order_codes83(p_id uuid) returns jsonb language plpgsql security definer set search_path='' as $$begin
 if not workshop_private.manage83() then raise exception 'Codes réservés à l’administration et à la modération.' using errcode='42501';end if;
 return(select coalesce(jsonb_agg(jsonb_build_object('id',i->>'id','label',i->>'label','code',coalesce((select c.code from workshop_private.product_codes83 c where c.product_id::text=i->>'id'),(select pc.code from workshop_private.catalog75 c join workshop_private.product_codes83 pc on pc.product_id=c.id where workshop_private.norm83(c.name)=workshop_private.norm83(i->>'label') limit 1),(select min(code) from workshop_private.codes83 where workshop_private.norm83(name)=workshop_private.norm83(i->>'label') having count(distinct code)=1)))),'[]') from public.workshop_order_requests r cross join lateral jsonb_array_elements(r.items) i where r.id=p_id and r.deleted_at is null);
end $$;
do $$begin if to_regprocedure('public.workshop_catalog76_before83(text,integer)') is null then alter function public.workshop_catalog76(text,integer) rename to workshop_catalog76_before83;end if;end $$;
create or replace function public.workshop_catalog76(p_section text,p_known integer default -1) returns jsonb language plpgsql security definer set search_path='' as $$declare r jsonb;begin
 r:=public.workshop_catalog76_before83(p_section,p_known);if jsonb_typeof(r->'items')='array' then r:=jsonb_set(r,'{items}',(select coalesce(jsonb_agg(x order by c.position,c.id),'[]') from jsonb_array_elements(r->'items') x left join workshop_private.catalog75 c on c.id::text=x->>'id'));end if;return r;
end $$;
create or replace function public.workshop_oil_restore83(p_id text) returns void language plpgsql security definer set search_path='' as $$begin
 if not workshop_private.manage83() then raise exception 'Action réservée aux responsables.' using errcode='42501';end if;
 perform 1 from workshop_private.oil_catalog72 where id=1 for update;
 if not exists(select 1 from workshop_private.oil_catalog72 t cross join lateral jsonb_array_elements(t.items) x where x->>'id'=p_id) then raise exception 'Référence introuvable.';end if;
 update workshop_private.oil_catalog72 t set items=(select jsonb_agg(case when x->>'id'=p_id then x||'{"unavailable":false}'::jsonb else x end order by n) from jsonb_array_elements(t.items) with ordinality a(x,n)),version=version+1 where id=1;
end $$;
create table if not exists workshop_private.carried83(source_id uuid,item_key text,target_id uuid,primary key(source_id,item_key));
alter table workshop_private.carried83 enable row level security;revoke all on workshop_private.carried83 from public,anon,authenticated;
do $$begin if to_regprocedure('public.workshop_validate_order_before83(uuid,integer)') is null then alter function public.workshop_validate_order(uuid,integer) rename to workshop_validate_order_before83;end if;end $$;
create or replace function public.workshop_validate_order(p_id uuid,p_version integer) returns jsonb language plpgsql security definer set search_path='' as $$declare src public.workshop_order_requests%rowtype;dest public.workshop_order_requests%rowtype;r jsonb;i jsonb;next_items jsonb;k text;week date;begin
 if not workshop_private.manage83() then raise exception 'Validation réservée aux responsables.' using errcode='42501';end if;
 perform pg_advisory_xact_lock(hashtextextended('order-carry83',0));select * into src from public.workshop_order_requests where id=p_id for update;
 r:=public.workshop_validate_order_before83(p_id,p_version);if src.status='validated' then return r;end if;
 if not exists(select 1 from jsonb_array_elements(src.items) x where coalesce((x->>'out_of_stock')::boolean,false)) then return r;end if;
 week:=coalesce(src.week_start,date_trunc('week',src.created_at at time zone 'Europe/Paris')::date)+7;
 loop
  select * into dest from public.workshop_order_requests where week_start=week for update;
  exit when dest.status='pending' and dest.deleted_at is null;week:=week+7;
  if week>coalesce(src.week_start,current_date)+370 then raise exception 'Aucune nouvelle semaine disponible pour le report.';end if;
 end loop;
 next_items:=dest.items;
 for i in select x from jsonb_array_elements(src.items) x where coalesce((x->>'out_of_stock')::boolean,false) loop
  k:=coalesce(nullif(i->>'id',''),workshop_private.norm83(i->>'label'));
  if exists(select 1 from jsonb_array_elements(next_items) x where x->>'id'=i->>'id' or workshop_private.norm83(x->>'label')=workshop_private.norm83(i->>'label')) then
   next_items:=(select jsonb_agg(case when x->>'id'=i->>'id' or workshop_private.norm83(x->>'label')=workshop_private.norm83(i->>'label') then x||jsonb_build_object('quantity',(x->>'quantity')::int+(i->>'quantity')::int,'out_of_stock',true) else x end order by n) from jsonb_array_elements(next_items) with ordinality a(x,n));
  else next_items:=next_items||jsonb_build_array(i||jsonb_build_object('carried_from',src.id));end if;
 end loop;
 if jsonb_array_length(next_items)>100 or exists(select 1 from jsonb_array_elements(next_items) x where (x->>'quantity')::int>999) then raise exception 'La commande suivante dépasse la capacité autorisée. Ajuste-la avant validation.';end if;
 update public.workshop_order_requests set items=next_items,version=version+1,updated_at=now() where id=dest.id;return r;
end $$;
revoke all on function workshop_private.norm83(text),public.workshop_catalog76_before83(text,integer),public.workshop_validate_order_before83(uuid,integer) from public,anon,authenticated;
revoke all on function public.workshop_order_codes83(uuid),public.workshop_oil_restore83(text),public.workshop_catalog76(text,integer),public.workshop_validate_order(uuid,integer) from public,anon;
grant execute on function public.workshop_order_codes83(uuid),public.workshop_oil_restore83(text),public.workshop_catalog76(text,integer),public.workshop_validate_order(uuid,integer) to authenticated;
notify pgrst,'reload schema';commit;
